import{z as p,x as E,o as s,c as d,q as n,j as r,D as e,d as o,s as i,S as l,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Strassen","description":"","frontmatter":{"title":"Strassen","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/strassen.md","filePath":"cs/strassen.md","lastUpdated":1791413859000}'),m={name:"cs/strassen.md"};function B(h,a,C,c,_,u){const t=E("Mermaid");return s(),d("div",null,[a[2]||(a[2]=n('<h1 id="strassen" tabindex="-1">Strassen <a class="header-anchor" href="#strassen" aria-label="Permalink to &quot;Strassen&quot;">​</a></h1><div class="epigraph"><p>$2\\times 2$ 矩阵七次乘加若干次加，代替八次乘；$n$ 阶递归 $O(n^{\\log_2 7})\\approx n^{2.807}$。</p><footer>—— 据 Strassen, Gaussian Elimination is not Optimal, 1969；CLRS 第 4、28 章整理</footer></div><p>上一课<a href="/cs/polynomial-inverse">多项式求逆</a>把多项式运算收到乘法。矩阵乘朴素 \\(n^3\\) 次标量乘。缺口是 Strassen：分块 \\(2\\times 2\\) 的 7 次乘。不重写 Karatsuba 的 3 次——同精神不同恒等式。后课高斯消元谈 \\(n^3\\) 的消元，与本课渐近对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(C=AB\\)，\\(n=2^k\\)。分成四块。Strassen 七个乘积 \\(P_i\\)（块的加减组合），再加减拼 \\(C\\) 的块。\\(T(n)=7T(n/2)+O(n^2)=\\Theta(n^{\\log_2 7})\\)。加法更多，数值稳定性比朴素差，阈值下切回 \\(O(n^3)\\)。</p><p>缺口是这次双线性恒等式。更快的 \\(\\omega\\) 记录（Coppersmith–Winograd 族）点名：理论 \\(\\omega\\lt 2.373\\)，实现仍常 Strassen 或朴素。</p><h3 id="不是高斯消元已经最优" tabindex="-1">不是高斯消元已经最优 <a class="header-anchor" href="#不是高斯消元已经最优" aria-label="Permalink to &quot;不是高斯消元已经最优&quot;">​</a></h3><p>Strassen 标题即针对消元里的矩阵乘。求逆、行列式也可到同一 \\(\\omega\\)。本课只乘。数值线性代数实践仍 BLAS 分块朴素乘为主。</p><p><span class="marginnote">Strassen 1969。Winograd 有加法更少的变体。后课高斯消元与线性基是 \\(O(n^3)\\) 结构，不假设已用 Strassen。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(n\\) 补到 2 的幂或剥层。递归七次。浮点注意误差累积。模意义下精确，加法次数仍贵。</p>',11)),(s(),r(l,null,{default:e(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20AB%5B%22A%2C%20B%20%E5%88%86%E5%9D%97%22%5D%20--%3E%20P%5B%227%20%E6%AC%A1%E5%9D%97%E4%B9%98%22%5D%0A%20%20P%20--%3E%20ADD%5B%22%E5%9D%97%E5%8A%A0%E5%87%8F%E6%8B%BC%20C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("p",null,"从朴素 8 次乘降到 7 次乘，省的是每一层递归顶层的乘法次数，代价是加法变多、数值误差变大。",-1)),(s(),r(l,null,{default:e(()=>[i(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPLIT%5B%222x2%20%E5%88%86%E5%9D%97%3A%20A11..A22%2C%20B11..B22%22%5D%20--%3E%20M%5B%22%E7%AE%97%207%20%E4%B8%AA%E4%B9%98%E7%A7%AF%20P1..P7%22%5D%0A%20%20M%20--%3E%20C1%5B%22%E5%8A%A0%E5%87%8F%E6%8B%BC%E5%87%BA%20C11%22%5D%0A%20%20M%20--%3E%20C2%5B%22%E5%8A%A0%E5%87%8F%E6%8B%BC%E5%87%BA%20C12%22%5D%0A%20%20M%20--%3E%20C3%5B%22%E5%8A%A0%E5%87%8F%E6%8B%BC%E5%87%BA%20C21%22%5D%0A%20%20M%20--%3E%20C4%5B%22%E5%8A%A0%E5%87%8F%E6%8B%BC%E5%87%BA%20C22%22%5D%0A%20%20C1%20--%3E%20CHK%7B%22%E5%9D%97%E5%A4%9F%E5%B0%8F%3F%22%7D%0A%20%20C2%20--%3E%20CHK%0A%20%20C3%20--%3E%20CHK%0A%20%20C4%20--%3E%20CHK%0A%20%20CHK%20--%20%22%E6%98%AF%22%20--%3E%20NAIVE%5B%22%E5%88%87%E5%9B%9E%E6%9C%B4%E7%B4%A0%E4%B9%98%22%5D%0A%20%20CHK%20--%20%22%E5%90%A6%22%20--%3E%20SPLIT%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<p><span class="marginnote">数字实例：\\(n=1024\\) 时，朴素乘约需 \\(1024^3\\approx 1.07\\times10^9\\) 次标量乘；Strassen 降到 \\(1024^{2.807}\\approx 2.8\\times10^8\\)（即 \\(7^{10}\\)）次量级——理论上乘法只剩约四分之一，但额外加减操作也是 \\(O(n^2)\\) 量级的开销，小矩阵上省的还不够加法赔的，所以要设阈值切回朴素。</span></p><p>并行七次乘可。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(2\\times 2\\) 一般需要 7 次乘（双线性复杂度下界相关）。递归把下界变成 \\(n^{\\log_2 7}\\)。与 FFT：多项式卷积不是矩阵乘，不要用 FFT 直接乘两个无关矩阵（除非特殊结构）。张量分解视角点名。</p><p><span class="marginnote">常见误区：初学者容易以为 Strassen 是「一个更好的公式」。实际上它是把乘法次数每层从 \\(8\\) 降到 \\(7\\)，让递归树每层少一份八分之一的分支——指数上只要降一点（\\(3\\to\\log_2 7\\approx 2.807\\)），大规模上就是数量级的差距，这正是分治对指数的杠杆。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 \\(\\omega\\) 的当前世界纪录证明。不写张量秩全文。后课默认：矩阵乘理论 \\(O(n^\\omega)\\)，\\(\\omega\\le\\log_2 7\\) 已够用；实现有阈值。下一课高斯消元与异或线性基。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>七次半阶乘，\\(O(n^{2.807})\\)。</li><li>小规模切回朴素；浮点要小心。</li><li>更快 \\(\\omega\\) 存在，本课用 Strassen。</li><li>出处：Strassen, 1969。</li></ul>',9))])}const D=p(m,[["render",B]]);export{f as __pageData,D as default};
